    /// Decodes active and empty DisasterManager records from the bounded
    /// `DisasterManager+Data` body.
    ///
    /// The manager boundary is checked against the following profiler tag.
    /// Active-record fields follow the inspected reader gates; the available
    /// map corpus contains no active disaster records.
    pub fn decode_disaster_manager_data(&self) -> Result<DisasterManagerData, CrpError> {
        let managers = self
            .manager_objects
            .as_deref()
            .ok_or_else(|| invalid(0, "manager object array is null"))?;
        let slot = unique_manager_slot(Some(managers), "DisasterManager+Data")?;
        let (body_start, next_tag_start) = self.manager_body_boundary(slot)?;
        let bytes = self
            .serialized_object_graph
            .get(body_start..next_tag_start)
            .ok_or_else(|| invalid(body_start, "DisasterManager body range is invalid"))?;
        let (data, consumed) = DisasterManagerData::decode(self.format_version, bytes)?;
        if consumed != bytes.len() {
            return Err(invalid(
                body_start + consumed,
                "DisasterManager fields do not end at the following manager tag",
            ));
        }
        Ok(data)
    }

    /// Decodes active DisasterManager records into a fixed-layout editor.
    pub fn decode_disaster_manager_editor(&self) -> Result<DisasterManagerEditor, CrpError> {
        Ok(self.decode_disaster_manager_data()?.into_editor())
    }

    /// Replaces DisasterManager flags, record values, and counters while
    /// preserving references and validating the following manager boundary.
    /// Re-encoding changed flags can resize the manager body.
    pub fn replace_disaster_manager_data(
        &mut self,
        edited: &DisasterManagerEditor,
    ) -> Result<(), CrpError> {
        if edited.format_version() != self.format_version {
            return Err(invalid(
                0,
                "edited DisasterManager version does not match this stream",
            ));
        }
        let current = self.decode_disaster_manager_data()?;
        if current.encode_unchanged().as_slice() != edited.original_body_bytes() {
            return Err(invalid(
                0,
                "DisasterManager bytes do not match the editor's source body",
            ));
        }
        let replacement = edited.encode()?;
        let managers = self
            .manager_objects
            .as_deref()
            .ok_or_else(|| invalid(0, "manager object array is null"))?;
        let slot = unique_manager_slot(Some(managers), "DisasterManager+Data")?;
        let (body_start, next_tag_start) = self.manager_body_boundary(slot)?;
        let source_body_end = body_start
            .checked_add(edited.original_body_bytes().len())
            .ok_or(CrpError::ArithmeticOverflow(
                "DisasterManager source body end",
            ))?;
        if source_body_end != next_tag_start {
            return Err(invalid(
                body_start,
                "DisasterManager source body does not reach the expected manager boundary",
            ));
        }
        let updated_next_tag_start =
            body_start
                .checked_add(replacement.len())
                .ok_or(CrpError::ArithmeticOverflow(
                    "DisasterManager replacement end",
                ))?;

        self.serialized_object_graph
            .get(body_start..source_body_end)
            .ok_or_else(|| invalid(body_start, "DisasterManager source body exceeds graph"))?;
        let mut candidate = self.serialized_object_graph.clone();
        candidate.splice(body_start..source_body_end, replacement.clone());
        let original_graph = std::mem::replace(&mut self.serialized_object_graph, candidate);
        let validation = self.decode_disaster_manager_data().and_then(|decoded| {
            if decoded.encode_unchanged() != replacement {
                return Err(invalid(
                    body_start,
                    "rewritten DisasterManager bytes failed exact body validation",
                ));
            }
            let (actual_body_start, actual_next_tag_start) = self.manager_body_boundary(slot)?;
            if actual_body_start != body_start || actual_next_tag_start != updated_next_tag_start {
                return Err(invalid(
                    body_start,
                    "rewritten DisasterManager did not preserve the shifted manager boundary",
                ));
            }
            Ok(())
        });
        if let Err(error) = validation {
            self.serialized_object_graph = original_graph;
            return Err(invalid(
                body_start,
                format!("rewritten DisasterManager body failed validation: {error}"),
            ));
        }
        Ok(())
    }

    /// Decodes the versioned radio-channel and radio-content fields in
    /// `AudioManager+Data`.
    ///
    /// Supports inner versions 164 and newer. The manager's closing two-byte
    /// profiler reference must be followed by the next manager tag. This
    /// locator supports the unique-string profiler tags observed in local maps
    /// and returns an error for other tag forms.
    pub fn decode_audio_manager_data(&self) -> Result<AudioManagerData, CrpError> {
        let field_range = self.audio_manager_field_range()?;
        let bytes = self
            .serialized_object_graph
            .get(field_range)
            .ok_or_else(|| invalid(0, "AudioManager field range exceeds manager graph"))?;
        let (data, consumed) = AudioManagerData::decode_prefix(self.format_version, bytes)?;
        if consumed != bytes.len() {
            return Err(invalid(
                consumed,
                "AudioManager field length disagrees with its versioned layout",
            ));
        }
        Ok(data)
    }

    /// Replaces existing channel/content flags and fixed-width record fields.
    ///
    /// The editor must come from this manager graph and preserve its active
    /// slots and prefab assignments. Changed flag arrays can resize the body;
    /// the following manager boundary is checked after replacement.
    pub fn replace_audio_manager_data(
        &mut self,
        edited: &AudioManagerEditor,
    ) -> Result<(), CrpError> {
        if edited.format_version() != self.format_version {
            return Err(invalid(
                0,
                "edited AudioManager version does not match this stream",
            ));
        }
        let field_range = self.audio_manager_field_range()?;
        let current = self
            .serialized_object_graph
            .get(field_range.clone())
            .ok_or_else(|| invalid(0, "AudioManager field range exceeds manager graph"))?;
        if current != edited.original_prefix() {
            return Err(invalid(
                field_range.start,
                "AudioManager bytes do not match the editor's source fields",
            ));
        }
        let replacement = edited.encode()?;

        let mut candidate = self.serialized_object_graph.clone();
        candidate.splice(field_range.clone(), replacement);
        let original_graph = std::mem::replace(&mut self.serialized_object_graph, candidate);
        if let Err(error) = self.decode_audio_manager_data() {
            self.serialized_object_graph = original_graph;
            return Err(invalid(
                field_range.start,
                format!("edited AudioManager fields failed boundary validation: {error}"),
            ));
        }
        Ok(())
    }

