    /// Replaces edited NaturalResourceManager direct grids, used-resource
    /// counters, and pollution-disposal rates. Re-encoding changed grids can
    /// resize the body; the following ImmaterialResourceManager bytes are
    /// retained and the new boundary is checked.
    pub fn replace_natural_resource_manager_data(
        &mut self,
        edited: &NaturalResourceManagerData,
    ) -> Result<(), CrpError> {
        if edited.format_version() != self.format_version {
            return Err(invalid(
                16,
                "edited NaturalResourceManager version does not match this stream",
            ));
        }
        let field_range = self.natural_resource_manager_field_range()?;
        let current_bytes = self
            .serialized_object_graph
            .get(field_range.clone())
            .ok_or_else(|| {
                invalid(
                    field_range.start,
                    "NaturalResourceManager body range is invalid",
                )
            })?;
        if current_bytes != edited.encode_unchanged() {
            return Err(invalid(
                field_range.start,
                "NaturalResourceManager bytes do not match the editor's source body",
            ));
        }
        let replacement = edited.encode()?;
        let mut candidate_graph = self.serialized_object_graph.clone();
        candidate_graph.splice(field_range.clone(), replacement.clone());
        let original_graph = std::mem::replace(&mut self.serialized_object_graph, candidate_graph);
        let validation = self
            .decode_natural_resource_manager_data()
            .and_then(|decoded| {
                if decoded.encode_unchanged() != replacement {
                    return Err(invalid(
                        field_range.start,
                        "rewritten NaturalResourceManager body does not match the edited fields",
                    ));
                }
                Ok(())
            });
        if let Err(error) = validation {
            self.serialized_object_graph = original_graph;
            return Err(invalid(
                field_range.start,
                format!("rewritten NaturalResourceManager body failed validation: {error}"),
            ));
        }
        Ok(())
    }

