    fn transfer_manager_with_noncanonical_counts() -> SimulationManagerData {
        let mut graph = profiler_tag("TransferManager");
        graph.extend_from_slice(&vec![0; 128 * 8]);
        let mut counts = vec![0_u16; 128 * 16];
        counts[0] = 1;
        for chunk in counts.chunks(64) {
            graph.push((chunk.len() - 1) as u8);
            for count in chunk {
                graph.extend_from_slice(&count.to_be_bytes());
            }
        }
        graph.extend_from_slice(&[
            0, 1, // Active offer.
            0, 0, // Not excluded.
            0, 6, // Priority.
            0, 7, // Amount.
            0, 8, // X.
            0, 9, // Z.
            0, 10, // Instance type.
            0, 0, 0, 0, 1, // Instance index.
            0x12, 0x34, // Closing profiler reference.
        ]);
        graph.extend(profiler_tag("NaturalResourceManager"));
        graph.extend_from_slice(&[0xaa, 0xbb]);

        let mut manager = manager_with_graph(graph);
        manager.format_version = 111_004;
        let mut references = vec![None; 10];
        references[8] = Some(ManagerObjectReference {
            object_id: 8,
            type_name: "TransferManager+Data, Assembly-CSharp".to_owned(),
        });
        references[9] = Some(ManagerObjectReference {
            object_id: 9,
            type_name: "NaturalResourceManager+Data, Assembly-CSharp".to_owned(),
        });
        manager.manager_objects = Some(references);
        manager
    }

    fn append_repeated_zero_encoded_byte_array(output: &mut Vec<u8>, count: usize) {
        if count == 0 {
            return;
        }
        output.extend_from_slice(&[0, 0]);
        let mut remaining = count - 1;
        while remaining > 0 {
            let run = remaining.min(128);
            output.push((0x7f + run) as u8);
            remaining -= run;
        }
    }

    fn natural_resource_manager_with_next(
        next_type: &str,
        next_tag_name: &str,
    ) -> SimulationManagerData {
        const CELLS: usize = 262_144;
        let mut graph = profiler_tag("NaturalResourceManager");
        for _ in 0..10 {
            append_repeated_zero_encoded_byte_array(&mut graph, CELLS);
        }
        for _ in 0..10 {
            graph.extend_from_slice(&[1]); // Two literals establish a zero delta.
            graph.extend_from_slice(&[0; 8]);
            graph.push(0xce); // Repeat the zero value 79 times to reach 81.
        }
        graph.extend_from_slice(&[0; 8 * 4]); // Used-resource counters.
        graph.extend_from_slice(&[0xfe, 0x03]); // Signed pollution-disposal rates.
        graph.extend_from_slice(&[0x12, 0x34]); // Closing profiler reference.
        graph.extend(profiler_tag(next_tag_name));
        graph.extend_from_slice(&[0xaa, 0xbb]);

        let mut manager = manager_with_graph(graph);
        manager.format_version = 265;
        let mut references = vec![None; 11];
        references[9] = Some(ManagerObjectReference {
            object_id: 9,
            type_name: "NaturalResourceManager+Data, Assembly-CSharp".to_owned(),
        });
        references[10] = Some(ManagerObjectReference {
            object_id: 10,
            type_name: next_type.to_owned(),
        });
        manager.manager_objects = Some(references);
        manager
    }

    fn immaterial_resource_manager_with_next(
        next_type: &str,
        next_tag_name: &str,
    ) -> SimulationManagerData {
        const FORMAT_VERSION: u32 = 265;
        const SLOTS: usize = 20;
        const LOCAL_VALUES: usize = 65_536 * SLOTS;
        let mut graph = profiler_tag("ImmaterialResourceManager");
        for _ in 0..2 {
            append_zero_encoded_long_array(&mut graph, LOCAL_VALUES);
        }
        for _ in 0..2 {
            graph.extend((0..SLOTS).flat_map(|index| (index as i32).to_be_bytes()));
        }
        for _ in 0..SLOTS {
            graph.extend_from_slice(&0_i64.to_be_bytes());
        }
        for _ in 0..2 {
            graph.extend((0..SLOTS).flat_map(|index| (index as i32).to_be_bytes()));
        }
        graph.extend_from_slice(&[0x12, 0x34]);
        graph.extend(profiler_tag(next_tag_name));
        graph.extend_from_slice(&[0xaa, 0xbb]);

        let mut manager = manager_with_graph(graph);
        manager.format_version = FORMAT_VERSION;
        let mut references = vec![None; 12];
        references[10] = Some(ManagerObjectReference {
            object_id: 10,
            type_name: "ImmaterialResourceManager+Data, Assembly-CSharp".to_owned(),
        });
        references[11] = Some(ManagerObjectReference {
            object_id: 11,
            type_name: next_type.to_owned(),
        });
        manager.manager_objects = Some(references);
        manager
    }

    fn electricity_manager_with_next(
        next_type: &str,
        next_tag_name: &str,
    ) -> SimulationManagerData {
        const FORMAT_VERSION: u32 = 265;
        let mut graph = profiler_tag("ElectricityManager");
        append_repeated_zero_encoded_byte_array(&mut graph, 65_536);
        graph.extend_from_slice(&[0; 4]); // Empty pulse-group and pulse-unit tables.
        append_zero_encoded_long_array(&mut graph, 32_768);
        graph.extend_from_slice(&[0; 8]); // Processed and conductive-cell counters.
        graph.push(1); // canContinue.
        graph.extend_from_slice(&[0x12, 0x34]); // Closing profiler reference.
        graph.extend(profiler_tag(next_tag_name));
        graph.extend_from_slice(&[0xaa, 0xbb]);

        let mut manager = manager_with_graph(graph);
        manager.format_version = FORMAT_VERSION;
        let mut references = vec![None; 13];
        references[11] = Some(ManagerObjectReference {
            object_id: 11,
            type_name: "ElectricityManager+Data, Assembly-CSharp".to_owned(),
        });
        references[12] = Some(ManagerObjectReference {
            object_id: 12,
            type_name: next_type.to_owned(),
        });
        manager.manager_objects = Some(references);
        manager
    }

    fn water_manager_with_next(next_type: &str, next_tag_name: &str) -> SimulationManagerData {
        water_manager_with_next_version(265, next_type, next_tag_name)
    }

    fn water_manager_with_next_version(
        format_version: u32,
        next_type: &str,
        next_tag_name: &str,
    ) -> SimulationManagerData {
        let mut graph = profiler_tag("WaterManager");
        append_zero_encoded_long_array(&mut graph, 65_536); // Water conductivity.
        append_zero_encoded_long_array(&mut graph, 65_536); // Heating conductivity.
        append_zero_encoded_long_array(&mut graph, 65_536); // Closest water segment.
        append_zero_encoded_long_array(&mut graph, 65_536); // Closest heating segment.
        graph.extend_from_slice(&1_u16.to_be_bytes()); // One water pulse group.
        graph.extend_from_slice(&[0; 14]); // Fixed-width water pulse-group record.
        if format_version >= 270 {
            graph.extend_from_slice(&[0; 4]); // Version-270 collect pressure.
        }
        graph.extend_from_slice(&1_u16.to_be_bytes()); // One water pulse unit.
        graph.extend_from_slice(&[0; 6]); // Fixed-width water pulse-unit record.
        graph.extend_from_slice(&[0; 8]); // Empty sewage and heating group/unit pairs.
        for _ in 0..9 {
            append_zero_encoded_long_array(&mut graph, 32_768);
        }
        append_zero_encoded_long_array(&mut graph, 32_768); // Node pollution.
        if format_version == 270 {
            append_zero_encoded_long_array(&mut graph, 32_768 / 8); // Bool collect-water selectors.
        } else if format_version >= 271 {
            append_zero_encoded_long_array(&mut graph, 32_768); // Collect-water pressure.
        }
        if format_version >= 272 {
            append_zero_encoded_long_array(&mut graph, 32_768); // Collect-sewage pressure.
        }
        graph.extend_from_slice(&[0; 8]); // Processed and conductive-cell counters.
        graph.push(1); // canContinue.
        graph.extend_from_slice(&[0xff, 0xff]); // Two null guide references.
        graph.extend_from_slice(&[0x12, 0x34]); // Closing profiler reference.
        graph.extend(profiler_tag(next_tag_name));
        graph.extend_from_slice(&[0xaa, 0xbb]);

        let mut manager = manager_with_graph(graph);
        manager.format_version = format_version;
        let mut references = vec![None; 14];
        references[12] = Some(ManagerObjectReference {
            object_id: 12,
            type_name: "WaterManager+Data, Assembly-CSharp".to_owned(),
        });
        references[13] = Some(ManagerObjectReference {
            object_id: 13,
            type_name: next_type.to_owned(),
        });
        manager.manager_objects = Some(references);
        manager
    }

    #[test]
    fn info_manager_mask_decodes_and_replaces_at_versioned_boundary() {
        for (version, original, replacement) in [
            (
                110_002,
                vec![0x12, 0x34, 0x56, 0x78],
                vec![0xa1, 0xb2, 0xc3, 0xd4],
            ),
            (
                110_003,
                vec![0x01, 0x23, 0x45, 0x67, 0x89, 0xab, 0xcd, 0xef],
                vec![0xfe, 0xdc, 0xba, 0x98, 0x76, 0x54, 0x32, 0x10],
            ),
        ] {
            let mut manager = info_manager_with_next(
                version,
                &original,
                "StatisticsManager",
                "StatisticsManager",
            );
            let tail_start =
                manager.serialized_object_graph.len() - profiler_tag("StatisticsManager").len();
            let original_tail = manager.serialized_object_graph[tail_start - 2..].to_vec();
            let mut edited = manager.decode_info_manager_data().unwrap();
            assert_eq!(edited.encode_unchanged(), original);
            let decoded_value = if version < 110_003 {
                u64::from(u32::from_be_bytes(original.as_slice().try_into().unwrap()))
            } else {
                u64::from_be_bytes(original.as_slice().try_into().unwrap())
            };
            assert_eq!(edited.visited_info_views(), decoded_value);

            let replacement_value = if version < 110_003 {
                u64::from(u32::from_be_bytes(
                    replacement.as_slice().try_into().unwrap(),
                ))
            } else {
                u64::from_be_bytes(replacement.as_slice().try_into().unwrap())
            };
            edited.set_visited_info_views(replacement_value).unwrap();
            manager.replace_info_manager_data(&edited).unwrap();
            assert_eq!(
                manager.decode_info_manager_data().unwrap().encode(),
                replacement
            );
            assert_eq!(
                &manager.serialized_object_graph[tail_start - 2..],
                original_tail
            );
        }
    }

    #[test]
    fn disaster_manager_editor_replaces_active_fields_and_rejects_stale_source() {
        let mut manager = disaster_manager_with_active_record();
        let original_graph = manager.serialized_object_graph().to_vec();
        let source_body = manager
            .decode_disaster_manager_data()
            .unwrap()
            .encode_unchanged();
        let body_start = profiler_tag("DisasterManager").len();
        let body_end = body_start + source_body.len();
        let original_following = original_graph[body_end..].to_vec();
        let mut stale_editor = manager.decode_disaster_manager_editor().unwrap();
        let mut edited = manager.decode_disaster_manager_editor().unwrap();
        assert_eq!(edited.records()[0].slot_index, 1);
        assert_eq!(edited.flags()[0], 1);
        edited.set_flag_bits(0, 3).unwrap();
        edited.records_mut()[0].intensity = Some(99);
        edited.records_mut()[0].casualty_count = Some(17);
        let expected_body = edited.encode().unwrap();
        assert_ne!(expected_body.len(), source_body.len());

        manager.replace_disaster_manager_data(&edited).unwrap();
        let decoded = manager.decode_disaster_manager_data().unwrap();
        assert_eq!(decoded.flags()[0], 3);
        assert_eq!(decoded.records()[0].intensity, Some(99));
        assert_eq!(decoded.records()[0].casualty_count, Some(17));
        assert_eq!(
            manager.serialized_object_graph().len(),
            original_graph.len() - source_body.len() + expected_body.len()
        );
        assert_eq!(
            &manager.serialized_object_graph()[body_start + expected_body.len()..],
            original_following
        );

        let rewritten_graph = manager.serialized_object_graph().to_vec();
        stale_editor.records_mut()[0].intensity = Some(1);
        assert!(
            manager
                .replace_disaster_manager_data(&stale_editor)
                .is_err()
        );
        assert_eq!(manager.serialized_object_graph(), rewritten_graph);
    }

