    #[test]
    fn audio_manager_flag_edits_resize_the_body_and_preserve_following_bytes() {
        let mut manager = audio_manager_with_three_channel_slots();
        let tag_len = profiler_tag("AudioManager").len();
        let original_body = manager.decode_audio_manager_data().unwrap().encoded_len();
        let following_start = tag_len + original_body;
        let following_bytes = manager.serialized_object_graph[following_start..].to_vec();
        let original_graph_len = manager.serialized_object_graph.len();

        let mut edited = manager.decode_audio_manager_data().unwrap().into_editor();
        assert_eq!(edited.channel_flags(), [0, 0, 1]);
        assert!(edited.set_channel_flag_bits(2, 0).is_err());
        edited.set_channel_flag_bits(2, 3).unwrap();
        let replacement = edited.encode().unwrap();
        assert_eq!(replacement.len(), original_body - 7);

        manager.replace_audio_manager_data(&edited).unwrap();
        assert_eq!(
            manager.serialized_object_graph.len(),
            original_graph_len - 7
        );
        assert_eq!(
            &manager.serialized_object_graph[tag_len + replacement.len()..],
            following_bytes
        );
        let decoded = manager.decode_audio_manager_data().unwrap();
        assert_eq!(decoded.channel_flags(), [0, 0, 3]);
        assert_eq!(decoded.radio_channels()[0].slot_index, 3);
    }

    #[test]
    fn transfer_manager_replacement_resizes_body_and_preserves_following_manager() {
        let mut manager = transfer_manager_with_noncanonical_counts();
        let natural_tag = profiler_tag("NaturalResourceManager");
        let natural_start = manager
            .serialized_object_graph
            .windows(natural_tag.len())
            .position(|window| window == natural_tag)
            .unwrap();
        let following_bytes = manager.serialized_object_graph[natural_start..].to_vec();
        let original_len = manager.serialized_object_graph.len();

        let mut edited = manager
            .decode_transfer_manager_data()
            .unwrap()
            .into_editor();
        assert_eq!(edited.reason_counts().len(), 128 * 16);
        edited.reason_counts_mut()[0] = 0;
        edited.set_offers(Vec::new()).unwrap();
        assert!(
            edited.encode().unwrap().len() < natural_start - profiler_tag("TransferManager").len()
        );
        manager.replace_transfer_manager_data(&edited).unwrap();

        assert!(manager.serialized_object_graph.len() < original_len);
        assert!(manager.serialized_object_graph.ends_with(&following_bytes));
        let decoded = manager.decode_transfer_manager_data().unwrap();
        assert_eq!(decoded.reason_counts()[0], 0);
        assert_eq!(decoded.reason_counts()[1], 0);
        assert!(decoded.offers().is_empty());

        let mut stale_manager = transfer_manager_with_noncanonical_counts();
        let stale_editor = stale_manager
            .decode_transfer_manager_data()
            .unwrap()
            .into_editor();
        stale_manager.serialized_object_graph[profiler_tag("TransferManager").len()] ^= 1;
        assert!(
            stale_manager
                .replace_transfer_manager_data(&stale_editor)
                .is_err()
        );
    }

