    #[test]
    fn natural_resource_manager_scalar_edits_replace_only_its_bounded_body() {
        let mut manager = natural_resource_manager_with_next(
            "ImmaterialResourceManager+Data, Assembly-CSharp",
            "ImmaterialResourceManager",
        );
        let original_graph = manager.serialized_object_graph.clone();
        let stale_editor = manager.decode_natural_resource_manager_data().unwrap();
        let mut edited = manager.decode_natural_resource_manager_data().unwrap();
        edited.set_used_resource_counter(2, 0xaabb_ccdd).unwrap();
        edited.set_pollution_disposal_rate(0, -17).unwrap();
        edited.set_pollution_disposal_rate(1, 29).unwrap();
        let expected_body = edited.encode().unwrap();

        manager
            .replace_natural_resource_manager_data(&edited)
            .unwrap();

        let body_start = profiler_tag("NaturalResourceManager").len();
        let next_tag = profiler_tag("ImmaterialResourceManager");
        let next_start = original_graph
            .windows(next_tag.len())
            .position(|window| window == next_tag)
            .unwrap();
        assert_eq!(manager.serialized_object_graph.len(), original_graph.len());
        assert_eq!(
            &manager.serialized_object_graph[..body_start],
            &original_graph[..body_start]
        );
        assert_eq!(
            &manager.serialized_object_graph[body_start..next_start],
            expected_body
        );
        assert_eq!(
            &manager.serialized_object_graph[next_start..],
            &original_graph[next_start..]
        );
        let decoded = manager.decode_natural_resource_manager_data().unwrap();
        assert_eq!(decoded.used_resource_counters().unwrap()[2], 0xaabb_ccdd);
        assert_eq!(decoded.pollution_disposal_rates(), Some([-17, 29]));

        let replaced_graph = manager.serialized_object_graph.clone();
        assert!(
            manager
                .replace_natural_resource_manager_data(&stale_editor)
                .is_err()
        );
        assert_eq!(manager.serialized_object_graph, replaced_graph);

        manager.format_version += 1;
        assert!(
            manager
                .replace_natural_resource_manager_data(&edited)
                .is_err()
        );
        assert_eq!(manager.serialized_object_graph, replaced_graph);
    }

