    #[test]
    fn tree_manager_editor_resizes_changed_encoded_columns_at_manager_boundary() {
        let mut flags = vec![0_u16; 262_143];
        flags[..3].fill(1);
        let mut encoded_flags = Vec::new();
        write_encoded_ushort_array(&mut encoded_flags, &flags);
        let encoded_flags_len = encoded_flags.len();
        let mut encoded_prefabs = Vec::new();
        write_encoded_ushort_array(&mut encoded_prefabs, &[1, 2, 3]);
        let mut encoded_x = Vec::new();
        write_encoded_ushort_array(&mut encoded_x, &[10, 20, 30]);

        let mut tree_body = encoded_flags;
        tree_body.extend_from_slice(&encoded_prefabs);
        tree_body.extend_from_slice(&[0, 0]); // Empty prefab-name scope.
        let x_offset = tree_body.len();
        tree_body.extend_from_slice(&encoded_x);
        write_encoded_ushort_array(&mut tree_body, &[40, 50, 60]);

        let mut graph = profiler_tag("TreeManager");
        let body_start = graph.len();
        graph.extend_from_slice(&tree_body);
        graph.extend_from_slice(&[0, 16]);
        graph.extend(profiler_tag("WeatherManager"));
        let mut manager = manager_with_graph(graph);
        manager.format_version = 194;
        let mut manager_objects = vec![None; 17];
        manager_objects[15] = Some(ManagerObjectReference {
            object_id: 15,
            type_name: "TreeManager+Data, Assembly-CSharp".to_owned(),
        });
        manager_objects[16] = Some(ManagerObjectReference {
            object_id: 16,
            type_name: "WeatherManager+Data, Assembly-CSharp".to_owned(),
        });
        manager.manager_objects = Some(manager_objects);

        let original_graph = manager.serialized_object_graph().to_vec();
        let original_graph_len = original_graph.len();
        let mut editor = manager.decode_tree_manager_editor().unwrap();
        editor.set_flag_bits(0, 3).unwrap();
        for tree in editor.trees_mut() {
            tree.position_x = 0;
        }
        let mut expected_graph = original_graph;
        let x_start = body_start + x_offset;
        expected_graph.splice(x_start..x_start + encoded_x.len(), [0x82]);
        let mut expected_flags = flags.clone();
        expected_flags[0] = 3;
        let mut encoded_expected_flags = Vec::new();
        write_encoded_ushort_array(&mut encoded_expected_flags, &expected_flags);
        let encoded_expected_flags_len = encoded_expected_flags.len();
        expected_graph.splice(
            body_start..body_start + encoded_flags_len,
            encoded_expected_flags,
        );
        assert_eq!(encoded_x.len(), 7);
        assert_eq!(
            expected_graph.len(),
            original_graph_len - (encoded_x.len() - 1) - encoded_flags_len
                + encoded_expected_flags_len
        );
        manager.replace_tree_manager_data(&editor).unwrap();

        assert_eq!(manager.serialized_object_graph(), expected_graph);
        assert_eq!(
            manager.serialized_object_graph().len(),
            expected_graph.len()
        );
        let (updated, weather_start) = manager.decode_tree_manager_prefix().unwrap();
        assert_eq!(updated.flags()[0], 3);
        assert!(updated.trees().iter().all(|tree| tree.position_x == 0));
        assert!(
            manager.serialized_object_graph()[weather_start..]
                .starts_with(&profiler_tag("WeatherManager"))
        );
        assert!(manager.replace_tree_manager_data(&editor).is_err());
        assert_eq!(manager.serialized_object_graph(), expected_graph);

        let mut expansion_editor = manager.decode_tree_manager_editor().unwrap();
        for (tree, position) in expansion_editor.trees_mut().iter_mut().zip([10, 20, 30]) {
            tree.position_x = position;
        }
        let expanded_column = [2, 0, 10, 0, 20, 0, 30];
        let mut expanded_graph = manager.serialized_object_graph().to_vec();
        let edited_x_start = x_start - encoded_flags_len + encoded_expected_flags_len;
        expanded_graph.splice(edited_x_start..edited_x_start + 1, expanded_column);
        manager
            .replace_tree_manager_data(&expansion_editor)
            .unwrap();
        assert_eq!(manager.serialized_object_graph(), expanded_graph);
        assert_eq!(
            expanded_graph.len(),
            original_graph_len - encoded_flags_len + encoded_expected_flags_len
        );
        let (expanded, weather_start) = manager.decode_tree_manager_prefix().unwrap();
        assert_eq!(
            expanded
                .trees()
                .iter()
                .map(|tree| tree.position_x)
                .collect::<Vec<_>>(),
            [10, 20, 30]
        );
        assert!(
            manager.serialized_object_graph()[weather_start..]
                .starts_with(&profiler_tag("WeatherManager"))
        );
    }

    #[test]
    fn weather_manager_locator_checks_closing_reference_and_vehicle_boundary() {
        for (profiler_name, manager_type) in [
            ("WeatherManager", "WeatherManager+Data"),
            ("WindManager", "WindManager+Data"),
        ] {
            let mut graph = profiler_tag(profiler_name);
            graph.extend([0xff; 2 * 128]);
            for value in [1.0_f32, 2.0, 3.0] {
                graph.extend_from_slice(&value.to_bits().to_be_bytes());
            }
            graph.extend_from_slice(&[0, 16]);
            let vehicle_tag = profiler_tag("VehicleManager");
            graph.extend_from_slice(&vehicle_tag);

            let mut manager = manager_with_graph(graph);
            manager.format_version = 231;
            let mut manager_objects = vec![None; 18];
            manager_objects[16] = Some(ManagerObjectReference {
                object_id: 16,
                type_name: format!("{manager_type}, Assembly-CSharp"),
            });
            manager_objects[17] = Some(ManagerObjectReference {
                object_id: 17,
                type_name: "VehicleManager+Data, Assembly-CSharp".to_owned(),
            });
            manager.manager_objects = Some(manager_objects);

            let (weather, end) = manager.decode_weather_manager_data().unwrap();
            assert_eq!(weather.wind_directions(), [1.0, 2.0, 3.0]);
            assert_eq!(
                end,
                manager.serialized_object_graph().len() - vehicle_tag.len()
            );
            assert!(manager.serialized_object_graph()[end..].starts_with(&vehicle_tag));
        }

        let mut graph = profiler_tag("WeatherManager");
        graph.extend([0xff; 2 * 128]);
        for value in [
            1.0_f32, 2.0, 3.0, // wind directions
            4.0, 5.0, 6.0, // temperature
            7.0, 8.0, 9.0, 10.0, // rain and fog
            11.0, 12.0, // clouds
            2.5,  // force weather (f32)
            14.0, // ground wetness
            15.0, 16.0, 17.0, 18.0, // northern lights and rainbow
        ] {
            graph.extend_from_slice(&value.to_bits().to_be_bytes());
        }
        let body_end = graph.len();
        graph.extend_from_slice(&[0, 16]);
        let vehicle_tag = profiler_tag("VehicleManager");
        graph.extend_from_slice(&vehicle_tag);
        let mut manager = manager_with_graph(graph);
        manager.format_version = 275;
        let mut manager_objects = vec![None; 18];
        manager_objects[16] = Some(ManagerObjectReference {
            object_id: 16,
            type_name: "WeatherManager+Data, Assembly-CSharp".to_owned(),
        });
        manager_objects[17] = Some(ManagerObjectReference {
            object_id: 17,
            type_name: "VehicleManager+Data, Assembly-CSharp".to_owned(),
        });
        manager.manager_objects = Some(manager_objects);
        let (weather, vehicle_start) = manager.decode_weather_manager_data().unwrap();
        assert_eq!(weather.force_weather_on(), Some(2.5));
        assert_eq!(weather.ground_wetness(), Some(14.0));
        assert_eq!(vehicle_start, body_end + 2);
        assert!(manager.serialized_object_graph()[vehicle_start..].starts_with(&vehicle_tag));

        let profiler_name = "WeatherManager";
        let mut graph = profiler_tag(profiler_name);
        graph.extend([0xff; 2 * 128]);
        graph.extend_from_slice(&[0.0_f32.to_bits().to_be_bytes(); 3].concat());
        let end_tag_start = graph.len();
        graph.extend_from_slice(&[0xfe, 0x00]);
        graph.extend(profiler_tag("VehicleManager"));
        let mut manager = manager_with_graph(graph);
        manager.format_version = 231;
        let mut manager_objects = vec![None; 18];
        manager_objects[16] = Some(ManagerObjectReference {
            object_id: 16,
            type_name: "WeatherManager+Data, Assembly-CSharp".to_owned(),
        });
        manager_objects[17] = Some(ManagerObjectReference {
            object_id: 17,
            type_name: "VehicleManager+Data, Assembly-CSharp".to_owned(),
        });
        manager.manager_objects = Some(manager_objects);
        assert!(manager.decode_weather_manager_data().is_err());
        assert_eq!(
            end_tag_start,
            profiler_tag(profiler_name).len() + 2 * 128 + 12
        );
    }

    #[test]
    fn weather_manager_height_edit_resizes_body_and_preserves_vehicle_boundary() {
        let mut graph = profiler_tag("WeatherManager");
        let body_start = graph.len();
        graph.extend([0xff; 2 * 128]);
        for value in [1.0_f32, 2.0, 3.0] {
            graph.extend_from_slice(&value.to_bits().to_be_bytes());
        }
        let body_len = graph.len() - body_start;
        graph.extend_from_slice(&[0x00, 0x10]);
        graph.extend(profiler_tag("VehicleManager"));

        let mut manager = manager_with_graph(graph);
        manager.format_version = 231;
        let mut manager_objects = vec![None; 18];
        manager_objects[16] = Some(ManagerObjectReference {
            object_id: 16,
            type_name: "WeatherManager+Data, Assembly-CSharp".to_owned(),
        });
        manager_objects[17] = Some(ManagerObjectReference {
            object_id: 17,
            type_name: "VehicleManager+Data, Assembly-CSharp".to_owned(),
        });
        manager.manager_objects = Some(manager_objects);

        let mut editor = manager.decode_weather_manager_editor().unwrap();
        editor.self_heights_mut()[0] = 0x1234;
        editor.wind_directions_mut()[1] = 9.0;
        let original_graph = manager.serialized_object_graph().to_vec();
        let next_tag = profiler_tag("VehicleManager");
        let old_next_start = original_graph
            .windows(next_tag.len())
            .position(|window| window == next_tag)
            .unwrap();
        let replacement = editor.encode().unwrap();
        let mut expected = original_graph.clone();
        expected.splice(
            body_start..body_start + body_len,
            replacement.iter().copied(),
        );
        manager.replace_weather_manager_data(&editor).unwrap();
        assert_eq!(manager.serialized_object_graph(), expected);
        assert_eq!(manager.serialized_object_graph().len(), expected.len());
        let (decoded, new_next_start) = manager.decode_weather_manager_data().unwrap();
        assert!(new_next_start > old_next_start);
        assert_eq!(
            &manager.serialized_object_graph()[new_next_start..],
            &original_graph[old_next_start..]
        );
        assert_eq!(decoded.self_heights()[0], 0x1234);
        assert_eq!(decoded.wind_directions(), [1.0, 9.0, 3.0]);
        assert!(manager.replace_weather_manager_data(&editor).is_err());
        assert_eq!(manager.serialized_object_graph(), expected);
        assert_eq!(body_len, 256 + 12);
    }

    #[test]
    fn weather_manager_version_276_raw_edit_preserves_vehicle_boundary() {
        let mut graph = profiler_tag("WeatherManager");
        graph.extend([0xff; 2 * 128]);
        for _ in 0..18 {
            graph.extend_from_slice(&0.0_f32.to_bits().to_be_bytes());
        }
        let compatibility_start = graph.len();
        graph.extend(0_u8..36);
        graph.extend_from_slice(&[0x00, 0x10]);
        graph.extend(profiler_tag("VehicleManager"));

        let mut manager = manager_with_graph(graph);
        manager.format_version = 276;
        let mut manager_objects = vec![None; 18];
        manager_objects[16] = Some(ManagerObjectReference {
            object_id: 16,
            type_name: "WeatherManager+Data, Assembly-CSharp".to_owned(),
        });
        manager_objects[17] = Some(ManagerObjectReference {
            object_id: 17,
            type_name: "VehicleManager+Data, Assembly-CSharp".to_owned(),
        });
        manager.manager_objects = Some(manager_objects);

        let original_graph = manager.serialized_object_graph().to_vec();
        let (_, original_vehicle_start) = manager.decode_weather_manager_data().unwrap();
        let mut editor = manager.decode_weather_manager_editor().unwrap();
        let compatibility = editor.version_276_compatibility_mut().unwrap();
        compatibility[0] = 0xa5;
        compatibility[35] = 0x5a;
        let mut expected = original_graph.clone();
        expected[compatibility_start] = 0xa5;
        expected[compatibility_start + 35] = 0x5a;

        manager.replace_weather_manager_data(&editor).unwrap();
        assert_eq!(manager.serialized_object_graph(), expected);
        let (decoded, vehicle_start) = manager.decode_weather_manager_data().unwrap();
        assert_eq!(vehicle_start, original_vehicle_start);
        assert_eq!(
            decoded.version_276_compatibility(),
            Some(&expected[compatibility_start..compatibility_start + 36])
        );
        assert!(
            manager.serialized_object_graph()[vehicle_start..]
                .starts_with(&profiler_tag("VehicleManager"))
        );
    }

